import re

def extract_code(reply: str) -> str:
    # 优先提取 ```python ... ``` 代码块
    match = re.search(r'```python\s*\n(.*?)```', reply, re.DOTALL | re.IGNORECASE)
    if match:
        return match.group(1).strip()

    # 没有代码块时，从首个 def/from/import 开头的行截取到结尾
    lines = reply.splitlines(keepends=True)
    start = None
    for i, line in enumerate(lines):
        stripped = line.lstrip()
        if re.match(r'^(?:def|from|import)\s', stripped):
            start = i
            break

    if start is not None:
        return ''.join(lines[start:]).strip()

    # 都没有则返回原文
    return reply

